// Build-time content template only. The media catalogue never creates routes.
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localAsset = value => {
 if (!/^\/(?:assets|sweet-media)\/[a-zA-Z0-9._/-]+$/.test(value ?? '') || value.includes('..')) throw new Error('Expected an approved local media asset');
 return escape(value);
};
export function renderVenueStory(s) {
 if (s.publicationStatus !== 'preview-approved') throw new Error('Owner preview approval required; held events cannot render');
 if (!['photo-video','video-only','photo-only'].includes(s.coverage)) throw new Error('Unknown coverage type');
 const photos=s.photos ?? []; const films=s.films ?? (s.film ? [s.film] : []); const hasFilm=s.coverage !== 'photo-only'; const hasPhotos=s.coverage !== 'video-only' && !s.photographyPending;
 if (hasFilm && (!films.length || films.some(f => !(f.provider === 'mediazilla' ? /^https:\/\/mediazilla\.com\/[A-Za-z0-9]+$/.test(f.embedUrl ?? '') : /^\d+$/.test(f.id ?? ''))))) throw new Error('Verified film required');
 if (!hasFilm && films.length) throw new Error('Photo-only coverage cannot include a film');
 if (hasPhotos && !photos.length) throw new Error('Verified photographs required');
 if (!hasPhotos && photos.length) throw new Error('Video-only coverage cannot include a photography collection');
 const label={'photo-video':'Wedding photography & film','video-only':'Wedding cinematography','photo-only':'Wedding photography'}[s.coverage];
 const e=escape;
 const photoMarkup=photos.map(p=>`<figure><a href="${localAsset(p.src)}" data-photo-viewer-link aria-label="View ${e(p.alt)}"><img src="${localAsset(p.small)}" srcset="${p.small === p.src ? `${localAsset(p.src)} ${p.width}w` : `${localAsset(p.small)} ${p.smallWidth ?? 640}w, ${localAsset(p.src)} ${p.smallWidth ? p.width : 1024}w`}" sizes="(max-width:650px) calc(100vw - 40px), (max-width:1100px) calc(100vw - 48px), 1072px" width="${Number(p.width)}" height="${Number(p.height)}" loading="lazy" decoding="async"${p.naturalRatio ? ` style="aspect-ratio:${Number(p.width)}/${Number(p.height)}"` : ''} alt="${e(p.alt)}"></a>${p.showCaption === true && p.caption ? `<figcaption>${e(p.caption)}</figcaption>` : ''}</figure>`).join('');
 let filmMarkup=hasFilm?films.map((film,index)=>`<section id="${index ? `wedding-film-${index+1}` : 'wedding-film'}" class="gv-film-section" aria-label="${e(film.eventName ?? s.couple)} wedding film"><div class="gv-film-heading"><h2>${films.length > 1 ? e(film.eventName ?? film.title) : 'The wedding film'}</h2></div><div class="gl-film-preview gv-film" style="aspect-ratio:${Number(film.width)}/${Number(film.height)}"><img src="${localAsset(film.poster)}" width="${Number(film.width)}" height="${Number(film.height)}" alt="${e(film.alt)}" fetchpriority="high" decoding="async"><button type="button" ${film.provider === 'mediazilla' ? `data-mediazilla-src="${e(film.embedUrl)}"` : `data-vimeo-id="${e(film.id)}"`} data-film-title="${e(film.title)}" aria-label="Play wedding film, ${e(film.title)}"><span>Play wedding film</span></button></div><p class="gv-caption">${e(film.eventName ?? s.couple)} · A film by GioLina Films</p>${film.coverage ? `<p class="gv-caption">${film.coverage === 'photo-video' ? 'Photography and cinematography by GioLina Films.' : 'Cinematography by GioLina Films.'}</p>` : ''}</section>`).join(''):'';
 if (s.kind === 'sweet-sixteen') filmMarkup=filmMarkup.replaceAll('The wedding film','The Sweet Sixteen film').replaceAll('Play wedding film','Play Sweet Sixteen film').replaceAll(' wedding film',' Sweet Sixteen film');
 if (!/^https:\/\//.test(s.venueUrl)) throw new Error('Official venue HTTPS URL required');
 let html = `<article class="gv-story gv-${s.coverage}"><header class="gv-intro"><p class="gv-kicker">${e(s.location)} · ${e(label)}</p><h1>${e(s.couple)}<br><em>${e(s.venue)}</em></h1><p class="gv-lede">${e(s.intro)}</p>${hasFilm&&hasPhotos?'<nav class="gv-story-nav" aria-label="Explore this wedding"><a href="#wedding-film">The film</a><a href="#wedding-photographs">The photographs</a></nav>':''}</header>${filmMarkup}${hasPhotos?`<section id="wedding-photographs" class="gv-editorial" aria-labelledby="gv-story-title"><p class="gv-kicker">Selected photographs</p><h2 id="gv-story-title">${e(s.photoHeading)}</h2><p>${e(s.photoIntro)}</p></section><section class="gv-gallery" aria-label="Selected photographs of ${e(s.photoEventName ?? s.couple)}">${photoMarkup}</section>`:''}<section class="gv-context" aria-labelledby="gv-context-title"><div><p class="gv-kicker">The setting · ${e(s.region)}</p><h2 id="gv-context-title">${e(s.venue)}</h2></div><div><p>${e(s.context)}</p><a class="gv-text-link" href="${e(s.venueUrl)}" target="_blank" rel="noopener noreferrer">Visit the venue website</a></div></section>${hasPhotos?'<div class="gv-collection-link"><a href="/photography/wedding-collection/">View the wedding photography collection</a></div>':''}<section class="gv-inquire" aria-labelledby="gv-inquire-title"><h2 id="gv-inquire-title">Your wedding at ${e(s.venue)}</h2><p>Share your date, venue and the coverage you have in mind.</p><a class="gv-button" href="/contact/">Inquire about your wedding</a><div class="gv-links"><a href="/cinematography/">Explore wedding films</a><a href="/photography/">Explore wedding photography</a></div></section>${s.next?`<section class="gv-next" aria-labelledby="gv-next-title"><p class="gv-kicker">Explore more wedding stories</p><h2 id="gv-next-title"><a href="${e(s.next.href)}">${e(s.next.label)}</a></h2></section>`:''}</article>${hasPhotos?'<script src="/photography-viewer.js" defer></script>':''}${films.some(f=>f.provider==='mediazilla')?'<script src="/mediazilla-player.js" defer></script>':''}`;
 if(s.kind==='sweet-sixteen') html=html.replaceAll('Wedding photography &amp; film','Sweet Sixteen photography &amp; film').replaceAll('Wedding photography & film','Sweet Sixteen photography &amp; film').replaceAll('Your wedding at','Your Sweet Sixteen at').replaceAll('Inquire about your wedding','Inquire about your Sweet Sixteen').replaceAll('Explore more wedding stories','Explore more Sweet Sixteen stories').replaceAll('Explore wedding films','Explore Sweet Sixteen films & photographs').replaceAll('href="/cinematography/"','href="/sweet-sixteen/"').replace('<a href="/photography/">Explore wedding photography</a>','').replace('href="/photography/wedding-collection/">View the wedding photography collection','href="/sweet-sixteen/">View the Sweet Sixteen collection');
 return html;
}

